parameters.jsCode:
// שולף טקסט גלוי + כתובת תמונה ראשונה + כתובת קובץ שמע ראשונה מתוך ה-HTML
// הגולמי שנשלף בצומת הקודם, ומנתב כל סוג תוכן שנמצא (0-3 items) לאותו צומת
// שהיה מטפל בו אילו הגיע ישירות דרך אחד משלושת מקורות הקלט האחרים. חיפוש
// המצוקה עצמו קורה בהמשך הזרימה הקיימת (Input Screening ואילך) - לא כאן.
const trigger = $('Website URL Input').item.json;
const body = trigger.body || trigger;
const user_id = body.user_id || "anonymous";
const incident_id = body.incident_id || "";

const html = $json.data || $json.body || "";
const withoutScripts = html
  .replace(/<script[\s\S]*?<\/script>/gi, "")
  .replace(/<style[\s\S]*?<\/style>/gi, "");

const pageText = withoutScripts
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/\s+/g, " ")
  .trim();

const imageMatch = withoutScripts.match(/<img[^>]+src=["']([^"']+)["']/i);
const audioMatch = withoutScripts.match(
  /<audio[^>]+src=["']([^"']+)["']|href=["']([^"']+\.(?:mp3|wav|ogg|m4a))["']/i
);

const items = [];
if (pageText) {
  items.push({ json: { _route: "text", text_content: pageText, user_id, incident_id } });
}
if (imageMatch) {
  items.push({ json: { _route: "image", image_url: imageMatch[1], user_id, incident_id } });
}
if (audioMatch) {
  items.push({ json: { _route: "voice", audio_url: audioMatch[1] || audioMatch[2], user_id, incident_id } });
}
return items;

// כאן קובעים בקלות מאיזו קבוצה/ערוץ בטלגרם למשוך וכמה הודעות בכל סריקה.
// את תדירות הסריקה (כל כמה זמן) קובעים בצומת הקודם (Telegram Poll Trigger),
// כי צמתי Trigger ב-n8n לא יכולים לקרוא ערך דינמי מצומת אחר - זו מגבלה של
// n8n עצמו, לא בחירה שלנו.
return [{
  json: {
    peer_id: "2097208579",
    limit: 10
  }
}];

// לוקח את מערך messages שחזר מ-RapidAPI (Telegram155 getHistory) והופך כל הודעה
// עם טקסט לפריט נפרד עם _route: "text", באותו פורמט שמצפה לו Route by Detected
// Content (בדיוק כמו Extract Website Content). הודעות בלי טקסט (מדיה בלבד) מדולגות.
//
// RapidAPI מחזיר את ההודעות מהחדשה לישנה (msg.id/msg.date יורדים). הופכים
// את הסדר (oldest-first) לפני היצירה, כדי שהשורות שנכתבות לאקסל המצטבר
// יהיו בסדר כרונולוגי, במקום הפוך בכל באטש (2026-07-20 באג שהתגלה בבדיקה).
// גם שולחים הלאה את msg.date (זמן שליחה אמיתי של ההודעה בטלגרם, unix
// epoch) בתור telegram_message_date - כדי שהעמודה timestamp באקסל תשקף מתי
// ההודעה נשלחה בפועל, לא מתי הריצה שלנו עיבדה אותה.
//
// לגבי תמונות/סרטונים: תגובת ה-API מכילה כרגע רק מבנה MTProto גולמי של המדיה
// (media.photo / media.video עם file_reference/dcid) ולא קישור URL שניתן להוריד
// ישירות - לכן עדיין לא מנתבים אותם ל-Image Analysis. מסמנים has_photo/has_video
// לצורך נראות בלבד, עד שנברר מול RapidAPI endpoint ייעודי להורדת מדיה.
const config = $('Telegram Poll Config').item.json;
const peerId = config.peer_id;

const response = $json;
const messages = [...(response.messages || [])].reverse();

const items = [];
for (const msg of messages) {
  const text = (msg.message || "").trim();
  if (!text) continue; // הודעת מדיה בלבד, אין מה לנתח

  const fromId = msg.from_id || {};
  const senderUserId = fromId.user_id;
  const userId = senderUserId ? `telegram:${senderUserId}` : "anonymous";

  const media = msg.media || {};
  const hasPhoto = Boolean(media.photo);
  const hasVideo = Boolean(media.video) || Boolean(media.document && (media.document.mime_type || "").startsWith("video/"));

  items.push({
    json: {
      _route: "text",
      text_content: text,
      user_id: userId,
      incident_id: `telegram-${peerId}-${msg.id}`,
      telegram_message_id: msg.id,
      telegram_message_date: msg.date,
      telegram_peer_id: peerId,
      has_photo: hasPhoto,
      has_video: hasVideo
    }
  });
}

return items;

// מקבץ פריטים לפי incident_id לפני איחוד טקסט: פריטים שחולקים incident_id
// (או שכולם בלי incident_id בכלל - למשל דף אינטרנט בודד עם טקסט+תמונה+קול
// שמתארים את אותו אירוע) מתמזגים לרשומה אחת עם טקסט מאוחד, כמו קודם.
// פריטים עם incident_id שונה זה מזה (למשל 20 הודעות טלגרם עצמאיות מסריקה
// אחת, שלכל אחת כבר יש incident_id ייחודי משלה שנקבע ב-Extract Telegram
// Messages) *לא* מתמזגים - כל אחד ממשיך כרשומה/אירוע נפרד משלו. בלי הקיבוץ
// הזה, 20 הודעות עצמאיות היו נטבעות זו בזו לאירוע מדומה אחד (2026-07-20 בדיקה
// שחשפה את זה).
//
// הבחירה איזה שדה טקסט לקחת מכל item נעשית לפי route/source שלו (לא לפי
// סדר עדיפות גנרי על השדות) כי safesignal.py תמיד ממלא placeholder ל-
// text_content בכל תגובה -- גם בתגובת התמלול -- כך שסדר עדיפות גנרי
// (text_content || TranscriptionText) תמיד "מנצח" עם ה-placeholder ומפספס
// את התמלול/הזיהוי האמיתיים.
const items = $input.all();

const groups = new Map(); // groupKey -> { texts: [], user_id, incident_id, message_timestamp }

for (const item of items) {
  const raw = item.json.body || item.json;
  const route = raw._route || raw.source || "";
  const groupKey = raw.incident_id || "";

  let t;
  if (route === "voice") t = raw.TranscriptionText;
  else if (route === "image") t = raw.DetectedText;
  else t = raw.text_content || raw.DetectedText || raw.TranscriptionText || raw.text;
  t = t || "";

  if (!groups.has(groupKey)) {
    groups.set(groupKey, { texts: [], user_id: "anonymous", incident_id: groupKey, message_timestamp: null });
  }
  const group = groups.get(groupKey);
  if (t && !group.texts.includes(t)) group.texts.push(t);
  if (raw.user_id && raw.user_id !== "anonymous") group.user_id = raw.user_id;
  if (group.message_timestamp === null && raw.telegram_message_date) group.message_timestamp = raw.telegram_message_date;
}

return Array.from(groups.values()).map((group) => ({
  json: {
    text_content: group.texts.join("\n"),
    user_id: group.user_id,
    incident_id:
      group.incident_id ||
      (typeof crypto !== "undefined" && crypto.randomUUID
        ? crypto.randomUUID()
        : `incident-${Date.now()}`),
    message_timestamp: group.message_timestamp,
  },
}));

// בניגוד לצומת ה-AWS S3 הישן, safesignal.py כבר מחזיר בחזרה את
// text_content/user_id/incident_id המקוריים (merged(body, ...)) + logged.
// עדיין משחזרים במפורש מהפריט שיצא מ-Unified Ingestion (Backend) כדי לא
// להסתמך על כך שה-endpoint ימשיך תמיד להדהד את כל השדות באותה צורה.
//
// צומת Code רץ פעם אחת על כל ה-items (run once for all items), אז חייבים
// לעבור על כולם עם $input.all() ולהחזיר item אחד לכל item נכנס. הגרסה
// הקודמת החזירה [{ json: ... }] קשיח - item יחיד בלבד - ולכן מתוך 19-20
// הודעות טלגרם שנכנסו, רק 1 יצאה והמשיכה לסיווג/Decision Agent, וה-19
// האחרות נבלעו בשקט (2026-07-20 באג שהתגלה כי המשתמש ביקש לוודא שכל
// ההודעות ממשיכות לצמתי ההחלטה).
const uploadResults = $input.all();
const originals = $('Unified Ingestion (Backend)').all();
return uploadResults.map((uploadResult, i) => ({
  json: { ...originals[i].json, raw_log: uploadResult.json },
}));

