parameters.jsCode:
// n8n-nodes-langchain.informationExtractor מחליף את $json בפלט שלו לכל item
// ({ output: {...} } בלבד) - מאבד את text_content/user_id/incident_id/
// screening_reason שהצמתים הבאים (Distress Classification, RAG, Decision
// Agent) צריכים. משחזרים אותם מהפריטים שיצאו מ-Passed Input Screening?,
// לפני החילוץ - אותו דפוס בדיוק כמו Restore Ingestion Data.
//
// קריטי: צומת Code רץ פעם אחת על כל ה-items (run once for all items) - חובה
// לעבור על כולם עם $input.all() ולא רק על $json/.item (item ראשון בלבד).
// הגרסה הקודמת עשתה בדיוק את הטעות הזו והחזירה item יחיד קשיח - מתוך באטש
// טלגרם עם כמה הודעות שעברו סינון, רק הראשונה הייתה ממשיכה לסיווג מצוקה,
// השאר נבלעות בשקט (2026-07-21 באג קריטי שהתגלה באותה סריקה שבה חשפנו את
// אותו דפוס בדיוק ב-Output Screening/Routing Result - זה אותו באג, בקוד
// שכתבתי היום בעצמי).
//
// גם אוכפים כאן, בקוד דטרמיניסטי (לא רק בהנחיית ה-LLM), את אותם חוקים
// עסקיים שהיו ב-info_extraction.py המקורי: סינון מילות-יחס/גיל כ"שם"
// (בן/בת/אני/וכו') ו-placeholder "אין שם" כשלא נמצא שם אמיתי - כדי שההחלפה
// תהיה זהה בפועל, לא רק "מבוקשת מהמודל".
const NON_NAME_WORDS = new Set([
  "בן", "בת", "אני", "אתה", "את", "הוא", "היא", "אנחנו", "אתם", "אתן", "הם", "הן",
  "ילד", "ילדה", "נער", "נערה", "מר", "גברת", "אדון"
]);
const NO_NAME_PLACEHOLDER = "אין שם";

const originals = $('Passed Input Screening?').all();

return $input.all().map((item, i) => {
  const original = originals[i].json;
  const extracted = item.json.output || {};

  const names = (Array.isArray(extracted.names) ? extracted.names : [])
    .filter(n => typeof n === "string" && n.trim() && !NON_NAME_WORDS.has(n.trim()));

  const ages = (Array.isArray(extracted.ages) ? extracted.ages : [])
    .filter(a => Number.isInteger(a) || /^\d+$/.test(String(a)))
    .map(a => parseInt(a, 10));

  return {
    json: {
      ...original,
      names: names.length ? names : [NO_NAME_PLACEHOLDER],
      addresses: Array.isArray(extracted.addresses) ? extracted.addresses : [],
      ages,
      phone_numbers: Array.isArray(extracted.phone_numbers) ? extracted.phone_numbers : [],
    },
  };
});

