parameters.jsCode:
// n8n-nodes-langchain.informationExtractor מחליף את $json בפלט שלו לכל item
// ({ output: {...} } בלבד, או { error: ... } אם onError=continueRegularOutput
// ונכשל) - מאבד את text_content/user_id/incident_id/names/addresses/ages/
// phone_numbers שהצמתים הבאים (RAG, Decision Agent) צריכים. משחזרים אותם
// מהפריטים שיצאו מ-Restore Extraction Context, לפני הסיווג - אותו דפוס
// בדיוק כמו Restore Ingestion Data / Restore Extraction Context. עוברים
// עם $input.all() (לא $json/.item של item יחיד) כדי לא לחזור על אותו באג
// שכבר תיקנו פעמיים היום.
//
// risk_level לא מתבקש מה-LLM בכלל, בכוונה - נגזר כאן מטבלת מיפוי קטגוריה->
// סיכון קבועה (CLASS_TO_RISK, זהה ל-distress_classification.py), כדי
// שרמת הסיכון תמיד תהיה עקבית עם הקטגוריה ולא תלויה בכך שה-LLM יבחר את
// שתיהן בהתאמה - אותה החלטת עיצוב בדיוק כמו במקור.
//
// אם הקריאה ל-Bedrock נכשלה (item.json.error קיים, בגלל onError=
// continueRegularOutput למעלה) - נופלים לאותה ברירת מחדל בטוחה כמו הקוד
// המקורי: "מצוקה רגשית" (medium), לא משמיטים את הפנייה.
const CLASS_TO_RISK = {
  "התאבדות/ארוע חירום": "high",
  "מצוקה רגשית": "medium",
  "חרם": "medium",
  "רגיל": "low",
};

const originals = $('Restore Extraction Context').all();

return $input.all().map((item, i) => {
  const original = originals[i].json;

  let label, summary;
  if (item.json.error) {
    label = "מצוקה רגשית";
    summary = `שגיאת סיווג מול Bedrock (${item.json.error}) - מנותב לבדיקה אנושית כברירת מחדל בטוחה`;
  } else {
    const extracted = item.json.output || {};
    label = CLASS_TO_RISK.hasOwnProperty(extracted.class) ? extracted.class : "מצוקה רגשית";
    summary = extracted.summary || "";
  }

  return {
    json: {
      ...original,
      class: label,
      risk_level: CLASS_TO_RISK[label] || "medium",
      summary,
    },
  };
});

