parameters.jsCode:
// תצוגה בלבד - Output Screening כבר רץ שרת צד (Bedrock Guardrails + Claude Haiku),
// כמצוין למעלה ב-Decision Agent (LangGraph + MCP) שלמעלה.
//
// צומת Code רץ פעם אחת על כל ה-items (run once for all items) - חובה
// לעבור על כולם עם $input.all() ולהחזיר item אחד לכל item נכנס. הגרסה
// הקודמת עבדה רק על $json (item ראשון בלבד) והחזירה מערך בגודל 1 קשיח -
// מתוך באטש של N הודעות, N-1 נבלעו בשקט ולא המשיכו כלל לניתוב/התרעה
// (2026-07-21 באג קריטי שהתגלה: הודעת "רק לא+" סווגה high-risk על ידי
// Decision Agent אך מעולם לא הגיעה ל-Send Emergency Email כי לא הייתה
// ה-item הראשון בבאטש).
return $input.all().map((item) => {
  const j = item.json;
  return {
    json: {
      ...j,
      output_screening_summary: `passed=${j.passed} reason="${j.screening_reason || ""}" retries=${j.output_retry_count ?? 0}`,
    },
  };
});

// תצוגה בלבד - risk_level כבר נקבע על ידי routing_by_risk_level_node ב-Python
// (שקרא ל-webhook risk-routing למטה בעמוד הזה).
//
// אותו תיקון כמו ב-Output Screening (Comprehend + ML) - Result: לעבור על כל
// ה-items עם $input.all() במקום להניח item יחיד, אחרת רוב הבאטש נבלע כאן.
return $input.all().map((item) => {
  const j = item.json;
  return {
    json: {
      ...j,
      routing_summary: `risk_level=${j.risk_level || "unknown"} action=${j.recommended_action || ""}`,
    },
  };
});
